<template><PageContainer><PageHeader eyebrow="SCR-MON-008" title="Capacite et saturation" description="Marge disponible et goulots de la plateforme."><template #actions><RouterLink class="mon-pill" to="/app/monitoring"><ArrowLeft/>Retour</RouterLink><button class="mon-btn mon-btn--primary" @click="store.chargerCapacite"><RefreshCw/>Actualiser</button></template></PageHeader><SectionBlock title="Calculs" description="MON-14 et MON-15 restent deux actions distinctes et permissionnees."><div class="mon-grid"><label class="mon-field"><span>Ressource</span><input v-model="ressource" maxlength="160" placeholder="postgres-pool"/></label><label class="mon-field"><span>Utilisation actuelle</span><input v-model.number="utilisation" type="number" min="0" step="any"/></label><label class="mon-field"><span>Capacite maximale</span><input v-model.number="max" type="number" min="0" step="any"/></label><label class="mon-field"><span>Taux saturation (%)</span><input v-model.number="taux" type="number" min="0" step="any"/></label></div><div class="mon-actions"><button v-if="canCapacity" class="mon-btn" @click="capacity">Calculer capacite</button><button v-if="canSaturation" class="mon-btn" @click="saturation">Calculer saturation</button></div></SectionBlock><LoadingState v-if="store.state.status==='loading'" title="Capacite en cours" message="Calcul des ressources Monitoring."/><ErrorState v-else-if="store.state.status==='error'" title="Capacite indisponible" :message="store.state.errorMessage??'Erreur technique.'"/><SectionBlock v-else title="Ressources" description="Capacite mesuree et marge restante."><MonitoringEmptyState v-if="!store.state.capacityData.length" title="Aucune mesure" message="Aucun snapshot de capacite n'est disponible."/><div v-else class="mon-kpi-grid"><article v-for="c in store.state.capacityData" :key="`${c.ressource}-${c.estimeeLe}`" class="mon-panel"><div class="mon-toolbar"><strong>{{c.ressource}}</strong><MonitoringStatusBadge :level="c.niveau"/></div><h2>{{c.margeDisponible}}</h2><div class="mon-muted">marge sur {{c.capaciteMax}} · utilise {{c.utilisationActuelle}}</div></article></div><div v-if="store.state.saturationData" class="mon-panel" style="margin-top:1rem"><div class="mon-toolbar"><div><strong>Saturation · {{store.state.saturationData.ressource}}</strong><div class="mon-muted">{{store.state.saturationData.taux}}% · goulot: {{store.state.saturationData.goulot?'oui':'non'}}</div></div><MonitoringStatusBadge :level="store.state.saturationData.niveau"/></div></div></SectionBlock></PageContainer></template>
<script setup lang="ts">import {ref} from 'vue';import {RouterLink} from 'vue-router';import {ArrowLeft,RefreshCw} from 'lucide-vue-next';import PageContainer from '../../../shared/layout/PageContainer.vue';import PageHeader from '../../../shared/layout/PageHeader.vue';import SectionBlock from '../../../shared/layout/SectionBlock.vue';import LoadingState from '../../../shared/ui/LoadingState.vue';import ErrorState from '../../../shared/ui/ErrorState.vue';import MonitoringEmptyState from '../components/MonitoringEmptyState.vue';import MonitoringStatusBadge from '../components/MonitoringStatusBadge.vue';import {hasMonitoringPermission} from '../access/monitoring-access';import {required,finiteNonNegative} from '../validation/monitoring-form.validation';import {useMonitoringStore} from '../stores/monitoring.store';import '../monitoring.css';const store=useMonitoringStore();const ressource=ref(''),utilisation=ref(0),max=ref(100),taux=ref(0);const canCapacity=hasMonitoringPermission('monitoring.capacity.calculate'),canSaturation=hasMonitoringPermission('monitoring.saturation.calculate');async function capacity(){if(required(ressource.value,'Ressource')||finiteNonNegative(utilisation.value,'Utilisation')||finiteNonNegative(max.value,'Capacite'))return;await store.calculerCapacite({ressource:ressource.value.trim(),utilisationActuelle:utilisation.value,capaciteMax:max.value})}async function saturation(){if(required(ressource.value,'Ressource')||finiteNonNegative(taux.value,'Taux'))return;await store.calculerSaturation({ressource:ressource.value.trim(),taux:taux.value})}</script>
